快速排序实现 C<pre><code>int partition(int A[], int low, int high) {
    int pivot = A[low];
    int i = low, j = high;
    while (i &lt; j) {
        while (i &lt; j &amp;&amp; A[j] &gt; pivot) j--;   // 右边第一个小于等于基准
        A[i] = A[j];
        while (i &lt; j &amp;&amp; A[i] &lt;= pivot) i++;  // 左边第一个大于基准
        A[j] = A[i];
    }
    A[i] = pivot;
    return i;
}

void quickSort(int A[], int low, int high) {
    if (low &gt; high) return;
    int p = partition(A, low, high);
    quickSort(A, low, p - 1);
    quickSort(A, p + 1, high);
}
