C<pre><code>vector&lt;int&gt; Dijkstra(vector&lt;vector&lt;int&gt;&gt;&amp; A, int v) {
    // A 为邻接矩阵，v 为源点编号，返回 dist 数组
    int n = A.size();
    vector&lt;int&gt; dist(n);
    vector&lt;bool&gt; S(n, false); // false 表示不在 S 数组中

    S[v] = true; // 把源点加入 S
    for (int i = 0; i &lt; n; i++) {
        dist[i] = A[v][i]; // 初始化为和源点的直线距离
    }

    for (int i = 0; i &lt; n-1; i++) { // 每次迭代把一个点加入 S，共 n-1 次
        int u = -1;      // 用于记录候选顶点
        int mindist = INF; // 从所有 dist 中找最小值
        for (int j = 0; j &lt; n; j++) {
            if (S[j] == false &amp;&amp; dist[j] &lt; mindist) {
                u = j;
                mindist = dist[j];
            }
        }
        if (u == -1) break; // 啥都没更新，说明已经做完了
        S[u] = true;
        for (int j = 0; j &lt; n; j++) {
            if (S[j] == false &amp;&amp; A[u][j] != 0 &amp;&amp; A[u][j] &lt; INF) {
                // u 和 j 之间连通，做松弛操作
                dist[j] = min(dist[j], dist[u] + A[u][j]);
            }
        }
    }
    return dist;
}
